234	basic_string<libzippp_uint8> ZipEntry::readAsBinaryString(ZipArchive::State state, libzippp_uint64 size) const {
235	    if (isNull()) { return basic_string<libzippp_uint8>(); }
236	    if (session.expired()) { return basic_string<libzippp_uint8>(); }
237	    libzippp_uint8* content = (libzippp_uint8*)zipFile->readEntry(*this, true, state, size);
238	    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
239	
240	    //see readAsText: the length must reflect the requested state (zero bytes inside the
241	    //content are preserved, the extra '\0' is only an allocation artifact)
242	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
243	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
244	    basic_string<libzippp_uint8> str(content, length);
245	    delete[] content;
246	    return str;
247	}
