249	int ZipEntry::readContent(std::ostream& ofOutput, ZipArchive::State state, libzippp_uint64 chunksize) const {
250	   //an invalid stream is reported first, as for a valid entry; the error codes below
251	   //are the ones guaranteed when the stream itself is valid
252	   if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
253	   //a null entry is invalid; a non-null entry whose opening ended is reported as coming
254	   //from a no-longer-open archive. The archive object itself may have been destroyed,
255	   //hence these checks must not dereference zipFile.
256	   if (isNull()) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
257	   if (session.expired()) { return LIBZIPPP_ERROR_NOT_OPEN; }
258	   return zipFile->readEntry(*this, ofOutput, state, chunksize);
259	}
