298	bool ZipArchive::isEntryUsable(const ZipEntry& entry) const {
299	    if (entry.isNull()) { return false; }
300	    if (entry.zipFile!=this) { return false; }
301	    //the entry must belong to the CURRENT opening of this archive: its session marker
302	    //is the one this archive holds right now
303	    std::shared_ptr<ZipEntrySession> entryOpening = entry.session.lock();
304	    return entryOpening && entryOpening==entrySession;
305	}
