307	ZipArchive::~ZipArchive(void) {
308	    close(); /* discard ??? */
309	
310	    //if the commit failed in close(), the archive is gone anyway: the adopted buffers
311	    //must not outlive it (on a successful close/discard this is a no-op)
312	    releaseAdoptedBuffers();
313	
314	    //whatever close() did (including a failed commit), the archive object itself is
315	    //gone: every entry obtained from any opening must be expired now
316	    endEntrySession();
317	
318	    // ensures all the values are clared
319	    zipHandle = nullptr;
320	    zipSource = nullptr;
321	    bufferData = nullptr;
322	    errorHandlingCallback = nullptr;
