364	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
365	    zip_error_t error;
366	    zip_error_init(&error);
367	
368	    /* create source from buffer */
369	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
370	    if (localZipSource == nullptr) {
371	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
372	        zip_error_fini(&error);
373	        return false;
374	    }
375	
376	    bool open = openSource(localZipSource, om, checkConsistency);
377	    if (open) {
378	        if (om==Write || om==New) {
379	            bufferData = data;
380	            bufferLength = size;
381	
382	            //prevents libzip to delete the source when closing the ZipArchive
383	            zip_source_keep(localZipSource);
384	        }
385	    } else {
386	        zip_source_free(localZipSource);
387	        localZipSource = nullptr;
388	    }
389	    return open;
390	}
