392	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
393	    int zipFlag = 0;
394	    if (om == ReadOnly) { zipFlag = 0; }
395	    else if (om == Write) { zipFlag = ZIP_CREATE; }
396	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
397	    else { return false; }
398	    if (checkConsistency) {
399	        zipFlag = zipFlag | ZIP_CHECKCONS;
400	    }
401	
402	    zip_error_t error;
403	    zip_error_init(&error);
404	
405	    /* open zip archive from source */
406	    zipHandle = zip_open_from_source(source, zipFlag, &error);
407	    if (zipHandle == nullptr) {
408	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
409	        zip_error_fini(&error);
410	        return false;
411	    }
412	    zip_error_fini(&error);
413	
414	    zipSource = source;
415	
416	#ifdef LIBZIPPP_WITH_ENCRYPTION
417	    if (isEncrypted()) {
418	        int result = zip_set_default_password(zipHandle, password.c_str());
419	        if (result != 0) {
420	            close();
421	            return false;
422	        }
423	    }
424	#endif
425	
426	    mode = om;
427	    beginEntrySession(); //entries created by this opening share this marker
428	    return true;
429	}
