477	void progress_callback(zip* /*archive*/, double progression, void* ud) {
478	    ZipArchive* za = static_cast<ZipArchive*>(ud);
479	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
480	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
481	        ZipProgressListener* listener = *it;
482	        listener->progression(progression);
483	    }
484	}
485	
486	int progress_cancel_callback(zip* /*archive*/, void* ud) {
487	    ZipArchive* za = static_cast<ZipArchive*>(ud);
488	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
489	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
490	        ZipProgressListener* listener = *it;
491	        if (listener->cancel())
492	          return 1;
493	    }
494	    return 0;
495	}
