497	int ZipArchive::close(void) {
498	    if (isOpen()) {
499	
500	        //do not handle zipSource at all because it will be deleted by libzip
501	        //directly when not necessary anymore
502	
503	        if (!listeners.empty()) {
504	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
505	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
506	        }
507	
508	        //avoid to reset the progress when unzipping
509	        if (mode != ReadOnly) {
510	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
511	        }
512	
513	        int result = zip_close(zipHandle);
514	        if (result!=0) {
515	            //typically a cancelled commit: the archive is still open and usable, the
516	            //session is left untouched so existing entries and their copies remain valid
517	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
518	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
519	        }
520	
521	        zipHandle = nullptr;
522	        //the opening really ended (even if the buffer readback below fails afterwards):
523	        //all entries obtained during it must expire now
524	        endEntrySession();
525	        //the commit consumed the sources: the buffers adopted with freeData=true are
526	        //no longer referenced by libzip and are released exactly once, here
527	        releaseAdoptedBuffers();
528	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
529	
530	        //push back the changes in the buffer
531	        int res_code = LIBZIPPP_OK;
532	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
533	            int srcOpen = zip_source_open(zipSource);
534	            if (srcOpen==0) {
535	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
536	                //buffer. We must never read into nor realloc *bufferData here: that memory
537	                //is the storage backing the libzip source we are currently reading from.
538	                //Reusing it aliases the source and, depending on the libzip version (i.e.
539	                //whether it takes ownership of the buffer when writing), it makes
540	                //zip_source_free() release a buffer that realloc() already moved/freed,
541	                //which results in a double-free (see double_free_report / fromWritableBuffer).
542	                zip_int64_t increment = 1024;
543	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
544	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
545	                char* tempBuffer = outBuffer;
546	                zip_int64_t tempBufferSize = capacity;
547	                zip_int64_t totalRead = 0;
548	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
549	                while(read>0) {
550	                    totalRead += read;
551	                    if (totalRead>=capacity) {
552	                        zip_int64_t newCapacity = capacity + increment;
553	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
554	                        if (grownBuffer==nullptr) {
555	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
556	                            ::free(outBuffer);
557	                            outBuffer = nullptr;
558	                            read = -1;
559	                            break;
560	                        }
561	                        outBuffer = grownBuffer;
562	                        capacity = newCapacity;
563	                    }
564	                    tempBuffer = outBuffer+totalRead;
565	                    tempBufferSize = capacity-totalRead;
566	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
567	                }
568	
569	                zip_source_close(zipSource);
570	
571	                if (outBuffer!=nullptr && read>=0) {
572	                    //freeing zipSource first guarantees libzip has released whatever it owns
573	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
574	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
575	                    zip_source_free(zipSource);
576	                    zipSource = nullptr;
577	
578	                    ::free(*bufferData);
579	                    *bufferData = outBuffer;
580	                    bufferLength = totalRead;
581	                } else {
582	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
583	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
584	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
585	                    zip_source_free(zipSource);
586	                    zipSource = nullptr;
587	                }
588	            } else {
589	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
590	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
591	
592	                zip_source_free(zipSource);
593	                zipSource = nullptr;
594	            }
595	        }
596	
597	        mode = NotOpen;
598	        return res_code;
599	    }
600	
601	    return LIBZIPPP_OK;
602	}
603	
604	void ZipArchive::discard(void) {
605	    if (isOpen()) {
606	        zip_discard(zipHandle);
607	        zipHandle = nullptr;
608	
609	        //the pending sources are gone: release the buffers adopted with freeData=true
610	        releaseAdoptedBuffers();
611	
612	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
613	            zip_source_free(zipSource);
614	            zipSource = nullptr;
615	        }
616	
617	        mode = NotOpen;
618	        endEntrySession(); //discarded opening: all its entries expire
619	    }
620	}
