734	
735	ZipEntry ZipArchive::createEntry(struct zip_stat* stat, State state) const {
736	    string name(stat->name);
737	    libzippp_uint64 index = stat->index;
738	    libzippp_uint64 size = stat->size;
739	
740	    /*
741	     * The compression method always comes from the entry itself, in the requested state:
742	     * the archive default compression is only a template for the files added or
743	     * overwritten afterwards and must never mask the method of an existing entry. A
744	     * configuration explicitly staged during this opening wins over the stat because
745	     * libzip reports ZIP_CM_DEFAULT as STORE in the current state and cannot report the
746	     * compression level at all (a level is not stored in the archive, hence it is zero
747	     * unless it was explicitly set during this opening).
748	     */
749	    libzippp_uint16 compMethod = stat->comp_method;
750	    libzippp_uint32 compLevel = 0;
751	    if (state==Current) {
752	        map<libzippp_uint64, libzippp_uint16>::const_iterator mit = entryCompressionMethods.find(index);
753	        if (mit!=entryCompressionMethods.end()) { compMethod = mit->second; }
754	        map<libzippp_uint64, libzippp_uint32>::const_iterator lit = entryCompressionLevels.find(index);
755	        if (lit!=entryCompressionLevels.end()) { compLevel = lit->second; }
756	    }
757	
758	    libzippp_uint16 encMethod = stat->encryption_method;
759	    libzippp_uint64 sizeComp = stat->comp_size;
760	    int crc = stat->crc;
761	    time_t time = stat->mtime;
762	
763	    return ZipEntry(this, entrySession, name, index, time, compMethod, compLevel, encMethod, size, sizeComp, crc);
764	}
765	
766	int ZipArchive::stateFlags(State state) {
767	    return state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
768	}
769	
770	ZipEntry ZipArchive::resolveEntry(const ZipEntry& zipEntry, State state, libzippp_uint64* outSize) const {
771	    if (outSize!=nullptr) { *outSize = 0; }
772	
773	    //a null-ZipEntry (e.g. obtained through getEntry in a state where the name does not
774	    //exist) cannot be resolved in any state, nor can an entry coming from another archive
775	    //or from an opening that has ended
776	    if (!isEntryUsable(zipEntry)) { return ZipEntry(); }
777	
778	    int flag = stateFlags(state);
779	    struct zip_stat stat;
780	    zip_stat_init(&stat);
781	
782	    //stat the (stable) slot in the requested state: this fails for an entry deleted in the
783	    //current state (read with Current) or a newly added entry (read with Original)
784	    if (zip_stat_index(zipHandle, zipEntry.getIndex(), flag, &stat)!=0) { return ZipEntry(); }
785	
786	    ZipEntry resolved = createEntry(&stat, state);
787	    if (outSize!=nullptr) { *outSize = stat.size; }
788	    return resolved;
789	}
790	
791	vector<ZipEntry> ZipArchive::getEntries(State state) const {
792	    if (!isOpen()) { return vector<ZipEntry>(); }
793	
794	    struct zip_stat stat;
795	    zip_stat_init(&stat);
796	
797	    vector<ZipEntry> entries;
798	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
799	    libzippp_int64 nbEntries = getNbEntries(state);
800	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
801	        int result = zip_stat_index(zipHandle, i, flag, &stat);
802	        if (result==0) {
803	            ZipEntry entry = createEntry(&stat, state);
804	            entries.push_back(entry);
805	        } else {
806	            //TODO handle read error => crash ?
807	        }
808	    }
809	    return entries;
810	}
