966	int ZipArchive::deleteEntry(const string& e) const {
967	    ZipEntry entry = getEntry(e);
968	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
969	    return deleteEntry(entry);
970	}
971	
972	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
973	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
974	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
975	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
976	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
977	
978	    bool isDir = entry.isDirectory();
979	    string newName = newNameIn;
980	    if (isDir) {
981	        //a '/' is automatically appended to the destination of a directory
982	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
983	    } else {
984	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
985	    }
986	
987	    string sourceName = entry.getName();
988	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
989	
990	    /*
991	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
992	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
993	     * reported with a null name by libzip and simply skipped.
994	     */
995	    struct RenameItem {
996	        zip_uint64_t index;
997	        string oldName;
998	        string targetName;
999	    };
1000	    vector<RenameItem> movedItems;
1001	    vector<string> externalNames;
1002	
1003	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
1004	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
1005	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
1006	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
1007	
1008	        string name(currentName);
1009	        bool participates = false;
1010	        string targetName;
1011	        if (isDir) {
1012	            if (name==sourceName) {
1013	                participates = true;
1014	                targetName = newName;
1015	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
1016	                participates = true; //descendant of the moved directory
1017	                targetName = newName + name.substr(sourceName.length());
1018	            }
1019	        } else {
1020	            participates = (name==sourceName);
1021	            targetName = newName;
1022	        }
1023	
1024	        if (participates) {
1025	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
1026	        } else {
1027	            externalNames.push_back(name);
1028	        }
1029	    }
1030	
1031	    //the source entry itself must be part of the current archive
1032	    bool sourceFound = false;
1033	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1034	        if (it->oldName==sourceName) { sourceFound = true; break; }
1035	    }
1036	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1037	
1038	    /*
1039	     * Detect conflicts against the CURRENT state only: any entry that does not participate
1040	     * in the move must not occupy the destination itself nor lie below it. Entries whose
1041	     * parent directories are only implicit (no explicit directory entry in the archive) are
1042	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
1043	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
1044	     */
1045	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
1046	        const string& external = *it;
1047	        if (isDir) {
1048	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
1049	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
1050	            }
1051	        } else {
1052	            if (external==newName) {
1053	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
1054	            }
1055	        }
1056	    }
1057	
1058	    /*
1059	     * Compute the (explicit) parent directories that will be missing once the entries have
1060	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
1061	     * existing as an entry, only its name changes), even when a moved entry's new parent
1062	     * chain goes through it.
1063	     */
1064	    vector<string> parentsToCreate;
1065	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1066	        //for a directory target (ending with '/'), the first parent to consider is above the
1067	        //target directory itself, hence the search starts at the penultimate separator
1068	        string::size_type searchPos = it->targetName.length()-1;
1069	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
1070	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
1071	        while(slash!=string::npos && slash>0) {
1072	            string parent = it->targetName.substr(0, slash+1);
1073	
1074	            //a moved destination already exists as an entry after the move
1075	            bool isMovedDestination = false;
1076	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
1077	                if (mit->targetName==parent) { isMovedDestination = true; break; }
1078	            }
1079	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
1080	
1081	            //an external entry already provides the directory (explicitly)
1082	            bool isExternal = false;
1083	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
1084	                if (*eit==parent) { isExternal = true; break; }
1085	            }
1086	            if (isExternal) { break; } //the prefix chain up to this directory already exists
1087	
1088	            bool alreadyScheduled = false;
1089	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
1090	                if (*pit==parent) { alreadyScheduled = true; break; }
1091	            }
1092	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
1093	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
1094	        }
1095	    }
1096	    //create the parents from the shallowest to the deepest
1097	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
1098	
1099	    /*
1100	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
1101	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
1102	     * are renamed to, and the freshly re-created parent directories are not touched.
1103	     */
1104	    std::sort(movedItems.begin(), movedItems.end(),
1105	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
1106	
1107	    vector<zip_uint64_t> renamedIndices;
1108	    vector<string> renamedOldNames;
1109	    bool failure = false;
1110	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1111	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
1112	        if (result!=0) { failure = true; break; }
1113	        renamedIndices.push_back(it->index);
1114	        renamedOldNames.push_back(it->oldName);
1115	    }
1116	
1117	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
1118	    vector<zip_uint64_t> createdDirIndices;
1119	    if (!failure) {
1120	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
1121	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
1122	            if (dirIndex<0) { failure = true; break; }
1123	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
1124	        }
1125	    }
1126	
1127	    if (failure) {
1128	        /*
1129	         * The move could not be completed: undo everything done during THIS call so that the
1130	         * archive is restored to its exact pre-call state. The directories created during
1131	         * the move are removed first (they may occupy the original names), then the renames
1132	         * are replayed in the reverse order (shallowest-first). Any other pending change is
1133	         * left untouched.
1134	         */
1135	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
1136	            zip_delete(zipHandle, *dit);
1137	        }
1138	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
1139	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
1140	        }
1141	        return LIBZIPPP_ERROR_UNKNOWN;
1142	    }
1143	
1144	    return (int)movedItems.size();
1145	}
1146	
1147	int ZipArchive::renameEntry(const string& e, const string& newName) const {
1148	    ZipEntry entry = getEntry(e);
1149	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1150	    return renameEntry(entry, newName);
1151	}
1152	
1153	void ZipArchive::releaseAdoptedBuffers(void) {
1154	    for(vector<void*>::iterator it=adoptedBuffers.begin() ; it!=adoptedBuffers.end() ; ++it) {
1155	        ::free(*it);
1156	    }
1157	    adoptedBuffers.clear();
1158	}
1159	
1160	bool ZipArchive::isArchiveCompressionApplicable(void) const {
1161	    if (!useArchiveCompressionMethod && compressionLevel==0) { return true; }
1162	
1163	    //a non-zero default level must be applicable to the default method: libzip does not
1164	    //reject an out-of-range DEFLATE level (it would be written as-is), so the documented
1165	    //range is enforced here, before anything is modified
1166	    libzippp_uint16 effectiveMethod = useArchiveCompressionMethod ? compressionMethod : (libzippp_uint16)ZIP_CM_DEFAULT;
1167	    if (!isCompressionLevelApplicable(effectiveMethod, compressionLevel)) { return false; }
1168	
1169	#ifdef LIBZIPPP_HAS_COMPRESSION_METHOD_SUPPORTED
1170	    if (useArchiveCompressionMethod) {
1171	        return zip_compression_method_supported(compressionMethodToLibzip(compressionMethod), 1)!=0;
1172	    }
1173	#endif
1174	    return true;
1175	}
1176	
1177	bool ZipArchive::isArchiveEncryptionApplicable(void) const {
1178	#ifdef LIBZIPPP_WITH_ENCRYPTION
1179	    if (isEncrypted()) {
1180	  #ifdef LIBZIPPP_HAS_ENCRYPTION_METHOD_SUPPORTED
1181	        return zip_encryption_method_supported((zip_uint16_t)encryptionMethod, 1)!=0;
1182	  #else
1183	        //cannot be checked beforehand: a failure is rolled back after the addition
1184	        return true;
1185	  #endif
1186	    }
1187	#endif
1188	    return true;
1189	}
1190	
1191	bool ZipArchive::createParentDirectories(const string& entryName, vector<libzippp_uint64>& createdDirIndices) const {
1192	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1193	    if (lastSlash==string::npos) { return true; } //no parent directory needed
1194	
1195	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1196	    while (nextSlash!=string::npos && nextSlash<=lastSlash) {
1197	        string pathToCreate = entryName.substr(0, nextSlash+1);
1198	        if (!hasEntry(pathToCreate)) {
1199	            libzippp_int64 dirIndex = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1200	            if (dirIndex<0) {
1201	                //a failed addition must not leave empty parent directories behind
1202	                rollbackCreatedDirectories(createdDirIndices);
1203	                return false;
1204	            }
1205	            createdDirIndices.push_back((libzippp_uint64)dirIndex);
1206	        }
1207	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1208	    }
1209	    return true;
1210	}
1211	
1212	void ZipArchive::rollbackCreatedDirectories(const vector<libzippp_uint64>& createdDirIndices) const {
1213	    //deepest directory first; only the directories created by the failed call are
1214	    //removed, pre-existing ones are never touched
1215	    for(vector<libzippp_uint64>::const_reverse_iterator it=createdDirIndices.rbegin() ; it!=createdDirIndices.rend() ; ++it) {
1216	        zip_delete(zipHandle, *it);
1217	    }
1218	}
1219	
1220	bool ZipArchive::installPreparedSource(const string& entryName, zip_source* source, const vector<libzippp_uint64>& createdDirIndices) const {
1221	    libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1222	    if (result<0) {
1223	        //the source was not adopted by libzip: release it without touching its data
1224	        zip_source_free(source);
1225	        rollbackCreatedDirectories(createdDirIndices);
1226	        return false;
1227	    }
1228	
1229	    zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1230	
1231	    bool settingsApplied = true;
1232	    bool compressionStaged = false;
1233	    if (useArchiveCompressionMethod || compressionLevel!=0) {
1234	        //both the default method and the default level selected on the archive apply to
1235	        //the actual write (a zero level keeps the default behaviour of libzip)
1236	        settingsApplied = zip_set_file_compression(zipHandle, result, compressionMethodToLibzip(compressionMethod), compressionLevel)==0;
1237	        compressionStaged = settingsApplied;
1238	    }
1239	#ifdef LIBZIPPP_WITH_ENCRYPTION
1240	    if (settingsApplied && isEncrypted()) {
1241	        settingsApplied = zip_file_set_encryption(zipHandle, result, encryptionMethod, nullptr)==0;
1242	    }
1243	#endif
1244	
1245	    if (!settingsApplied) {
1246	        /*
1247	         * Last-resort rollback: the applicability of the selected compression and
1248	         * encryption methods was checked before anything was changed, so this is only
1249	         * reachable on an unexpected libzip failure. The entry is reverted and the
1250	         * directories created by this call are removed; every other pending change
1251	         * (other entries, deletions, renames, comments) is left untouched. Reverting
1252	         * the entry also frees the source (which never owns the caller's data here).
1253	         */
1254	        zip_unchange(zipHandle, (zip_uint64_t)result);
1255	        rollbackCreatedDirectories(createdDirIndices);
1256	        return false;
1257	    }
1258	
1259	    if (compressionStaged) {
1260	        //the archive defaults were applied to the entry: they are its staged compression
1261	        //configuration for the rest of this opening (see entryCompressionMethods)
1262	        entryCompressionMethods[(libzippp_uint64)result] = compressionMethod;
1263	        entryCompressionLevels[(libzippp_uint64)result] = compressionLevel;
1264	    }
1265	    return true;
1266	}
1267	
1268	bool ZipArchive::addFile(const string& entryName, const string& file) const {
1269	    if (!isOpen()) { return false; }
1270	    if (mode==ReadOnly) { return false; } //adding not allowed
1271	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1272	
1273	    //the source file must be readable: a missing file must not leave any trace
1274	    //(neither a new entry nor parent directories) in the archive
1275	    FILE* probe = fopen(file.c_str(), "rb");
1276	    if (probe==nullptr) { return false; }
1277	    fclose(probe);
1278	
1279	    //the compression and encryption methods selected on the archive must be applicable
1280	    //by this libzip: this is checked before anything is changed so that a failure
1281	    //neither leaves a new entry behind nor silently falls back to weaker settings
1282	    if (!isArchiveCompressionApplicable()) { return false; }
1283	    if (!isArchiveEncryptionApplicable()) { return false; }
1284	
1285	    vector<libzippp_uint64> createdDirIndices;
1286	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1287	
1288	    zip_source* source = zip_source_file(zipHandle, file.c_str(), 0, -1);
1289	    if (source==nullptr) {
1290	        //unable to create the zip_source
1291	        rollbackCreatedDirectories(createdDirIndices);
1292	        return false;
1293	    }
1294	    return installPreparedSource(entryName, source, createdDirIndices);
1295	}
1296	
1297	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1298	    if (!isOpen()) { return false; }
1299	    if (mode==ReadOnly) { return false; } //adding not allowed
1300	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1301	
1302	    //a null buffer is only valid for an empty content; anything else is rejected
1303	    //before the archive is touched (the caller keeps the ownership of the data)
1304	    if (data==nullptr && length>0) { return false; }
1305	
1306	    //see addFile: the selected compression/encryption must be applicable beforehand
1307	    if (!isArchiveCompressionApplicable()) { return false; }
1308	    if (!isArchiveEncryptionApplicable()) { return false; }
1309	
1310	    vector<libzippp_uint64> createdDirIndices;
1311	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1312	
1313	    /*
1314	     * The buffer is always handed to libzip with freep=0, even when freeData is true:
1315	     * the ownership is transferred to the archive (see adoptedBuffers) only once the
1316	     * data has been fully accepted. Hence a failed call never frees the caller's
1317	     * memory and a successful one guarantees the buffer is released exactly once,
1318	     * when the pending changes are committed or discarded.
1319	     */
1320	    zip_source* source = zip_source_buffer(zipHandle, data, length, 0);
1321	    if (source==nullptr) {
1322	        //unable to create the zip_source
1323	        rollbackCreatedDirectories(createdDirIndices);
1324	        return false;
1325	    }
1326	    if (!installPreparedSource(entryName, source, createdDirIndices)) { return false; }
1327	
1328	    if (freeData && data!=nullptr) {
1329	        adoptedBuffers.push_back(const_cast<void*>(data));
1330	    }
1331	    return true;
1332	}
1333	
1334	bool ZipArchive::addData(const std::string& entryName, const std::basic_string<libzippp_uint8> data) const {
1335	    /*
1336	     * The argument is a copy that is destroyed when this method returns: its content
1337	     * must be copied again into a buffer owned by the archive (through the freeData
1338	     * contract) so that the staged source never references the dead argument when the
1339	     * changes are committed or read back.
1340	     */
1341	    if (data.empty()) { return addData(entryName, nullptr, 0, false); }
1342	    void* copy = malloc(data.size());
1343	    if (copy==nullptr) { return false; }
1344	    memcpy(copy, data.data(), data.size());
1345	    if (!addData(entryName, copy, data.size(), true)) {
1346	        //the ownership was not transferred: the copy is still ours to release
1347	        ::free(copy);
1348	        return false;
1349	    }
1350	    return true;
1351	}
1352	
1353	bool ZipArchive::addEntry(const string& entryName) const {
1354	    if (!isOpen()) { return false; }
1355	    if (mode==ReadOnly) { return false; } //adding not allowed
1356	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1357	
1358	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1359	    while (nextSlash!=string::npos) {
1360	        string pathToCreate = entryName.substr(0, nextSlash+1);
1361	        if (!hasEntry(pathToCreate)) {
1362	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1363	            if (result==-1) { return false; }
1364	        }
1365	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1366	    }
1367	
1368	    return true;
1369	}
1370	
1371	void ZipArchive::removeProgressListener(ZipProgressListener* listener) {
1372	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
1373	        ZipProgressListener* l = *it;
1374	        if (l==listener) {
1375	            listeners.erase(it);
1376	            break;
1377	        }
1378	    }
1379	}
1380	
1381	void ZipArchive::setCompressionMethod(CompressionMethod comp)
1382	{
1383	    useArchiveCompressionMethod = comp!=CompressionMethod::DEFAULT;
1384	    compressionMethod = convertCompressionToLibzip(comp);
1385	}
1386	
1387	CompressionMethod ZipArchive::getCompressionMethod(void) const {
1388	    return convertCompressionFromLibzip(compressionMethod);
1389	}
1390	
1391	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
1392	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1393	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){ ofOutput.write((char*)data, size); return bool(ofOutput); };
1394	    return readEntry(zipEntry, writeFunc, state, chunksize);
1395	}
1396	
1397	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1398	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1399	    //null entries, entries from other archives and entries from a previous opening are
1400	    //rejected before any data delivery (the output stream/callback is left untouched)
1401	    if (!isEntryUsable(zipEntry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1402	
1403	    //resolve the entry in the requested state: its existence and uncompressed size depend
1404	    //on the state. When it does not exist in the state, no data is delivered at all.
1405	    libzippp_uint64 maxSize = 0;
1406	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1407	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1408	
1409	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1410	
1411	    int flag = stateFlags(state);
1412	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1413	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1414	
1415	    int iRes = LIBZIPPP_OK;
1416	
1417	    //an empty content succeeds without reading anything; a single zero-length delivery is
1418	    //still signalled to the output (this matches the historical behavior)
1419	    if (maxSize==0) {
1420	        if (!writeFunc("", 0)) {
1421	            zip_fclose(zipFile);
1422	            return LIBZIPPP_ERROR_OWRITE_FAILURE;
1423	        }
1424	        zip_fclose(zipFile);
1425	        return LIBZIPPP_OK;
1426	    }
1427	
1428	    //only allocate what a single delivery may need (the whole content when it is smaller
1429	    //than the chunk size) instead of the chunk size in every case
1430	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1431	    char* data = NEW_CHAR_ARRAY(bufferSize)
1432	    if (data!=nullptr) {
1433	        //stream the exact, state-resolved length in successive chunks: this delivers the
1434	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1435	        //the content length are all handled by the same loop)
1436	        libzippp_uint64 remaining = maxSize;
1437	        while (remaining>0) {
1438	            libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1439	            libzippp_int64 result = zip_fread(zipFile, data, toRead);
1440	            if (result<0) {
1441	                iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1442	                break;
1443	            }
1444	            if (static_cast<libzippp_uint64>(result)!=toRead) {
1445	                iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1446	                break;
1447	            }
1448	            if (!writeFunc(data, toRead)) {
1449	                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1450	                break;
1451	            }
1452	            remaining -= toRead;
1453	        }
1454	        delete[] data;
1455	    } else {
1456	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1457	    }
1458	    zip_fclose(zipFile);
1459	    return iRes;
1460	}
