+static int seekIstreamSourceFile(FILE* file, libzippp_uint64 offset) {
+#ifdef _WIN32
+    return _fseeki64(file, (__int64)offset, SEEK_SET);
+#else
+    return fseek(file, (long)offset, SEEK_SET);
+#endif
