using namespace libzippp;
using namespace std;

// generates `total` bytes on the fly, no seeking
class GenBuf : public streambuf {
public:
    GenBuf(size_t total) : remaining(total), counter(0) {}
protected:
    virtual int_type underflow() {
        if (remaining==0) return traits_type::eof();
        return traits_type::to_int_type((char)(counter%256));
    }
    virtual int_type uflow() {
        if (remaining==0) return traits_type::eof();
        char c = (char)(counter%256);
        ++counter; --remaining;
        return traits_type::to_int_type(c);
    }
private:
    size_t remaining;
    size_t counter;
};

